  1	///|
  2	pub let usage : String = "Usage: orca-env-devsy <status|stop [--force]|resume> --provider <name> [--jobs <n>]\n       orca-env-devsy recipe <create|resume|suspend|destroy|recover|restart>\n       orca-env-devsy <recover|restart>\n"
  3	
  4	///|
  5	priv struct BulkOptions {
  6	  provider : String
  7	  jobs : Int32
  8	  force : Bool
  9	}
 10	
 11	///|
 12	fn bulk_options(mode : String, args : Array[String]) -> BulkOptions raise {
 13	  let mut provider = None
 14	  let mut jobs = 4
 15	  let mut force = false
 16	  let mut i = 0
 17	  while i < args.length() {
 18	    match args[i] {
 19	      "--provider" if i + 1 < args.length() && provider is None => {
 20	        i += 1
 21	        provider = Some(args[i])
 22	      }
 23	      "--jobs" if i + 1 < args.length() => {
 24	        i += 1
 25	        jobs = @string.parse_int(args[i])
 26	      }
 27	      "--force" if mode == "stop" && !force => force = true
 28	      _ => raise AdapterError("Invalid bulk option: " + args[i])
 29	    }
 30	    i += 1
 31	  }
 32	  guard provider is Some(provider) &&
 33	    valid_context(provider) &&
 34	    jobs > 0 &&
 35	    jobs <= 64 else {
 36	    raise AdapterError(
 37	      "--provider is required; --jobs must be between 1 and 64",
 38	    )
 39	  }
 40	  { provider, jobs, force, }
 41	}
 42	
 43	///|
 44	async fn observe_activity(state : Json) -> Json {
 45	  let directory = required(state, "tunnelDirectory")
 46	  let pairing = if @fs.exists(directory + "/pairing-code") {
 47	    @fs.read_file(directory + "/pairing-code").text()
 48	  } else {
 49	    ""
 50	  }
 51	  let script = (if field(state, "orcaVolume") is Some(_) {
 52	      "ORCA_USER_DATA_PATH=/workspaces/.orca/.profile "
 53	    } else {
 54	      ""
 55	    }) +
 56	    "ELECTRON_RUN_AS_NODE=1 \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" -e " +
 57	    quote(activity_probe_source())
 58	  let (input, writer) = @process.write_to_process()
 59	  defer writer.close()
 60	  let (output, reader) = @process.read_from_process()
 61	  defer output.close()
 62	  let sink = @process.redirect_to_file("/dev/null", shared=true)
 63	  defer sink.close()
 64	  @async.with_timeout(30000, async fn() {
 65	    @async.with_task_group(async fn(group) {
 66	      let child = @process.spawn(
 67	        group,
 68	        "ssh",
 69	        ssh_args(state, services=false) + [script],
 70	        stdin=input,
 71	        stdout=reader,
 72	        stderr=sink,
 73	      )
 74	      let reading = group.spawn(async fn() {
 75	        let buffer = @buffer.Buffer()
 76	        let bytes = FixedArray::make(4096, b'\x00')
 77	        while true {
 78	          let count = output.read(bytes)
 79	          if count == 0 {
 80	            break
 81	          }
 82	          guard buffer.length() + count <= 4194304 else {
 83	            raise AdapterError("Activity response too large")
 84	          }
 85	          buffer.write_bytes(Bytes::from_array(bytes[:count].to_owned()))
 86	        }
 87	        @utf8.decode(buffer.to_bytes())
 88	      })
 89	      let payload : Json = { "pairingCode": pairing }
 90	      writer.write(payload.stringify())
 91	      writer.close()
 92	      guard child.wait() == 0 else {
 93	        raise AdapterError("Remote activity probe failed")
 94	      }
 95	      let value = @json.parse(reading.wait())
 96	      guard field(value, "schemaVersion") == Some(Json::number(1)) &&
 97	        ["idle", "active", "unknown"].contains(required(value, "activity")) else {
 98	        raise AdapterError("Invalid activity response")
 99	      }
100	      value
101	    })
102	  })
103	}
